package yq

import (
	"fmt"
	"strings"
)

// ---------------------------------------------------------------------------
// YAML parser
// ---------------------------------------------------------------------------

type yparser struct {
	src       []byte
	pos       int
	line      int // 1-based
	lineStart int

	pending     []string // accumulated comment lines waiting for a node
	seenComment bool

	anchors map[string]*Node
}

type yamlError struct {
	msg string
}

func (e *yamlError) Error() string { return e.msg }

func newYAMLParser(src []byte) *yparser {
	return &yparser{src: src, line: 1, anchors: map[string]*Node{}}
}

func (p *yparser) errf(format string, args ...interface{}) error {
	return &yamlError{msg: fmt.Sprintf(format, args...)}
}

func (p *yparser) eof() bool { return p.pos >= len(p.src) }

func (p *yparser) ch() byte {
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func (p *yparser) at(o int) byte {
	i := p.pos + o
	if i < 0 || i >= len(p.src) {
		return 0
	}
	return p.src[i]
}

// col returns the 0-based column of the current position.
func (p *yparser) col() int { return p.pos - p.lineStart }

func (p *yparser) adv() {
	if p.pos < len(p.src) {
		if p.src[p.pos] == '\n' {
			p.line++
			p.lineStart = p.pos + 1
		}
		p.pos++
	}
}

func (p *yparser) advN(n int) {
	for i := 0; i < n; i++ {
		p.adv()
	}
}

func isBlank(c byte) bool { return c == ' ' || c == '\t' }

func (p *yparser) skipBlanks() {
	for !p.eof() && isBlank(p.ch()) {
		p.adv()
	}
}

// atComment reports whether a comment starts at the current position.
func (p *yparser) atComment() bool {
	if p.ch() != '#' {
		return false
	}
	if p.col() == 0 {
		return true
	}
	return isBlank(p.at(-1))
}

// atLineEnd reports whether only a comment or newline remains on this line.
func (p *yparser) atLineEnd() bool {
	return p.eof() || p.ch() == '\n' || p.atComment()
}

// restOfLine returns the text from pos to the end of the line.
func (p *yparser) restOfLine() string {
	e := p.pos
	for e < len(p.src) && p.src[e] != '\n' {
		e++
	}
	return string(p.src[p.pos:e])
}

func (p *yparser) skipToNewline() {
	for !p.eof() && p.ch() != '\n' {
		p.adv()
	}
}

// takeLineComment consumes a trailing comment on the current line and returns it.
func (p *yparser) takeLineComment() string {
	p.skipBlanks()
	if p.atComment() {
		start := p.pos
		p.skipToNewline()
		return strings.TrimRight(string(p.src[start:p.pos]), " \t")
	}
	return ""
}

// skipBlanksAndComments moves to the next line that has content, collecting
// comments into p.pending.  Blank lines seen before the first comment are
// discarded; blank lines after a comment are retained (as empty entries).
func (p *yparser) skipBlanksAndComments() {
	for {
		start := p.pos
		p.skipBlanks()
		if p.eof() {
			return
		}
		if p.ch() == '\n' {
			// blank line
			if p.seenComment {
				p.pending = append(p.pending, "")
			}
			p.adv()
			continue
		}
		if p.atComment() {
			cs := p.pos
			p.skipToNewline()
			p.pending = append(p.pending, strings.TrimRight(string(p.src[cs:p.pos]), " \t"))
			p.seenComment = true
			if !p.eof() {
				p.adv()
			}
			continue
		}
		p.pos = start
		p.line = p.line // unchanged
		// restore to line start position for indentation measurement
		p.pos = start
		p.skipBlanks()
		return
	}
}

func (p *yparser) takeComments() string {
	if len(p.pending) == 0 {
		return ""
	}
	s := strings.Join(p.pending, "\n")
	p.pending = nil
	p.seenComment = false
	return s
}

func (p *yparser) hasPending() bool { return len(p.pending) > 0 }

// ---------------------------------------------------------------------------
// document level
// ---------------------------------------------------------------------------

func (p *yparser) atDocMarker(marker string) bool {
	if p.col() != 0 {
		return false
	}
	if p.pos+3 > len(p.src) {
		return false
	}
	if string(p.src[p.pos:p.pos+3]) != marker {
		return false
	}
	c := p.at(3)
	return c == 0 || c == '\n' || c == ' ' || c == '\t' || c == '\r'
}

func (p *yparser) atDocStart() bool { return p.atDocMarker("---") }
func (p *yparser) atDocEnd() bool   { return p.atDocMarker("...") }

// ParseDocuments parses a YAML stream into a list of document root nodes.
func (p *yparser) ParseDocuments() ([]*Node, error) {
	var docs []*Node
	sawAny := false
	for {
		p.skipBlanksAndComments()
		if p.eof() {
			break
		}
		explicit := false
		var docLead []string
		for {
			if p.ch() == '%' && p.col() == 0 {
				docLead = append(docLead, p.restOfLine())
				p.skipToNewline()
				p.skipBlanksAndComments()
				continue
			}
			if p.atDocStart() {
				explicit = true
				p.advN(3)
				p.skipBlanks()
				if p.atLineEnd() {
					lc := p.takeLineComment()
					if lc != "" {
						p.pending = append(p.pending, lc)
						p.seenComment = true
					}
					if !p.eof() {
						p.adv()
					}
					p.skipBlanksAndComments()
					if p.eof() || p.atDocStart() || p.atDocEnd() {
						break
					}
					continue
				}
				break
			}
			break
		}
		_ = docLead
		if p.eof() {
			if explicit || !sawAny {
				n := nullNode()
				n.HeadComment = p.takeComments()
				docs = append(docs, n)
				sawAny = true
			}
			break
		}
		if p.atDocEnd() {
			p.advN(3)
			p.skipToNewline()
			if explicit {
				n := nullNode()
				n.HeadComment = p.takeComments()
				docs = append(docs, n)
				sawAny = true
			}
			continue
		}
		if p.atDocStart() {
			// empty document
			n := nullNode()
			docs = append(docs, n)
			sawAny = true
			continue
		}
		node, err := p.parseBlockNodeAtLineStart(p.col())
		if err != nil {
			return nil, err
		}
		sawAny = true
		// trailing comments belong to the last node of the document
		p.skipBlanksAndComments()
		if p.hasPending() {
			attachFoot(node, p.takeComments())
		}
		docs = append(docs, node)
		if p.atDocEnd() {
			p.advN(3)
			p.skipToNewline()
		}
	}
	if len(docs) == 0 {
		docs = append(docs, nullNode())
	}
	return docs, nil
}

// attachFoot places a foot comment on the deepest last element of a node.
func attachFoot(n *Node, comment string) {
	if comment == "" {
		return
	}
	target := n
	for {
		if target.Kind == MappingNode && len(target.Content) >= 2 {
			target = target.Content[len(target.Content)-2]
			continue
		}
		if target.Kind == SequenceNode && len(target.Content) >= 1 {
			target = target.Content[len(target.Content)-1]
			continue
		}
		break
	}
	if target.FootComment == "" {
		target.FootComment = comment
	} else {
		target.FootComment += "\n" + comment
	}
}

// ---------------------------------------------------------------------------
// properties (anchors and tags)
// ---------------------------------------------------------------------------

func (p *yparser) parseProps() (anchor, tag string, err error) {
	for {
		p.skipBlanks()
		switch p.ch() {
		case '&':
			p.adv()
			start := p.pos
			for !p.eof() && !isBlank(p.ch()) && p.ch() != '\n' && !strings.ContainsRune("[]{},", rune(p.ch())) {
				p.adv()
			}
			anchor = string(p.src[start:p.pos])
		case '!':
			start := p.pos
			p.adv()
			if p.ch() == '<' {
				for !p.eof() && p.ch() != '>' {
					p.adv()
				}
				if p.ch() == '>' {
					p.adv()
				}
			} else {
				if p.ch() == '!' {
					p.adv()
				}
				for !p.eof() && !isBlank(p.ch()) && p.ch() != '\n' && !strings.ContainsRune("[]{},", rune(p.ch())) {
					p.adv()
				}
			}
			tag = string(p.src[start:p.pos])
		default:
			return anchor, tag, nil
		}
	}
}

// resolveTagText converts source tag syntax into the canonical form.
func resolveTagText(t string) string {
	if t == "" {
		return ""
	}
	if strings.HasPrefix(t, "!<") && strings.HasSuffix(t, ">") {
		inner := t[2 : len(t)-1]
		if strings.HasPrefix(inner, "tag:yaml.org,2002:") {
			return "!!" + inner[len("tag:yaml.org,2002:"):]
		}
		return t
	}
	return t
}

// ---------------------------------------------------------------------------
// block nodes
// ---------------------------------------------------------------------------

// parseBlockNodeAtLineStart parses a node that begins at the first content
// character of a line, at column `indent`.
func (p *yparser) parseBlockNodeAtLineStart(indent int) (*Node, error) {
	head := p.takeComments()
	startLine, startCol := p.line, p.col()+1
	anchor, tagText := "", ""
	if p.ch() == '&' || p.ch() == '!' {
		var err error
		anchor, tagText, err = p.parseProps()
		if err != nil {
			return nil, err
		}
		if p.atLineEnd() {
			lc := p.takeLineComment()
			if !p.eof() {
				p.adv()
			}
			p.skipBlanksAndComments()
			if p.eof() || p.col() <= indent || p.atDocStart() || p.atDocEnd() {
				n := nullNode()
				n.HeadComment = head
				n.LineComment = lc
				n.Anchor = anchor
				n.Line, n.Column = startLine, startCol
				p.applyTag(n, tagText)
				p.registerAnchor(n)
				return n, nil
			}
			n, err := p.parseBlockNodeAtLineStart(p.col())
			if err != nil {
				return nil, err
			}
			n.HeadComment = joinComments(head, n.HeadComment)
			if lc != "" {
				n.LineComment = lc
			}
			if anchor != "" {
				n.Anchor = anchor
			}
			n.Line, n.Column = startLine, startCol
			p.applyTag(n, tagText)
			p.registerAnchor(n)
			return n, nil
		}
	}

	// sequence entry?
	if p.ch() == '-' && (p.at(1) == ' ' || p.at(1) == '\t' || p.at(1) == '\n' || p.pos+1 >= len(p.src)) {
		n, err := p.parseBlockSeq(indent)
		if err != nil {
			return nil, err
		}
		n.HeadComment = joinComments(head, n.HeadComment)
		n.Anchor = anchor
		n.Line, n.Column = startLine, startCol
		p.applyTag(n, tagText)
		p.registerAnchor(n)
		return n, nil
	}

	// explicit key?
	if p.ch() == '?' && (p.at(1) == ' ' || p.at(1) == '\n' || p.pos+1 >= len(p.src)) {
		n, err := p.parseBlockMap(indent, nil, head)
		if err != nil {
			return nil, err
		}
		n.Anchor = anchor
		n.Line, n.Column = startLine, startCol
		p.applyTag(n, tagText)
		p.registerAnchor(n)
		return n, nil
	}

	// otherwise: scalar / flow, possibly a mapping key
	first, isKey, err := p.parseNodeOrKey(indent)
	if err != nil {
		return nil, err
	}
	if isKey {
		n, err := p.parseBlockMap(indent, first, head)
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			n.Anchor = anchor
		}
		n.Line, n.Column = startLine, startCol
		p.applyTag(n, tagText)
		p.registerAnchor(n)
		return n, nil
	}
	first.HeadComment = joinComments(head, first.HeadComment)
	if anchor != "" {
		first.Anchor = anchor
	}
	if tagText != "" {
		p.applyTag(first, tagText)
	}
	first.Line, first.Column = startLine, startCol
	p.registerAnchor(first)
	return first, nil
}

func joinComments(a, b string) string {
	if a == "" {
		return b
	}
	if b == "" {
		return a
	}
	return a + "\n" + b
}

func (p *yparser) registerAnchor(n *Node) {
	if n.Anchor != "" {
		p.anchors[n.Anchor] = n
	}
}

func (p *yparser) applyTag(n *Node, tagText string) {
	if tagText == "" {
		return
	}
	t := resolveTagText(tagText)
	n.Tag = t
	if n.Kind == ScalarNode {
		n.Style |= TaggedStyle
	}
}

// parseNodeOrKey parses a scalar or flow node at the current position and
// reports whether it is followed by a ':' value indicator.
func (p *yparser) parseNodeOrKey(indent int) (*Node, bool, error) {
	startLine, startCol := p.line, p.col()+1
	anchor, tagText, err := p.parseProps()
	if err != nil {
		return nil, false, err
	}
	var n *Node
	switch p.ch() {
	case '"':
		s, err := p.scanDoubleQuoted()
		if err != nil {
			return nil, false, err
		}
		n = scalarNode(tagStr, s)
		n.Style = DoubleQuotedStyle
	case '\'':
		s, err := p.scanSingleQuoted()
		if err != nil {
			return nil, false, err
		}
		n = scalarNode(tagStr, s)
		n.Style = SingleQuotedStyle
	case '[', '{':
		n, err = p.parseFlow()
		if err != nil {
			return nil, false, err
		}
	case '|', '>':
		n, err = p.parseBlockScalar(indent)
		if err != nil {
			return nil, false, err
		}
	case '*':
		p.adv()
		st := p.pos
		for !p.eof() && !isBlank(p.ch()) && p.ch() != '\n' && !strings.ContainsRune("[]{},", rune(p.ch())) {
			p.adv()
		}
		n = &Node{Kind: AliasNode, Value: string(p.src[st:p.pos])}
	default:
		s, multiline, err := p.scanPlain(indent, false)
		if err != nil {
			return nil, false, err
		}
		n = scalarNode("", s)
		_ = multiline
	}
	n.Line, n.Column = startLine, startCol
	if anchor != "" {
		n.Anchor = anchor
	}
	if tagText != "" {
		p.applyTag(n, tagText)
	}
	if n.Tag == "" && n.Kind == ScalarNode {
		n.Tag = resolveScalarTag(n.Value)
	}
	// is it a key?
	save := p.snapshot()
	p.skipBlanks()
	if p.ch() == ':' {
		nx := p.at(1)
		if nx == ' ' || nx == '\t' || nx == '\n' || p.pos+1 >= len(p.src) {
			return n, true, nil
		}
	}
	p.restore(save)
	return n, false, nil
}

type snap struct {
	pos, line, lineStart int
}

func (p *yparser) snapshot() snap { return snap{p.pos, p.line, p.lineStart} }
func (p *yparser) restore(s snap) { p.pos, p.line, p.lineStart = s.pos, s.line, s.lineStart }

// parseBlockSeq parses a block sequence whose entries are at column `indent`.
func (p *yparser) parseBlockSeq(indent int) (*Node, error) {
	seq := emptySeq()
	seq.Line, seq.Column = p.line, p.col()+1
	for {
		if p.eof() || p.atDocStart() || p.atDocEnd() {
			break
		}
		if p.col() != indent || p.ch() != '-' {
			break
		}
		nx := p.at(1)
		if !(nx == ' ' || nx == '\t' || nx == '\n' || p.pos+1 >= len(p.src)) {
			break
		}
		head := p.takeComments()
		p.adv() // '-'
		item, err := p.parseAfterIndicator(indent, true)
		if err != nil {
			return nil, err
		}
		item.HeadComment = joinComments(head, item.HeadComment)
		item.Parent = seq
		seq.Content = append(seq.Content, item)

		p.skipBlanksAndComments()
		if p.eof() {
			break
		}
		if p.col() < indent || (p.col() == indent && p.ch() != '-') {
			break
		}
		if p.hasPending() && p.col() == indent && p.ch() == '-' {
			continue
		}
	}
	if p.hasPending() && !p.eof() && p.col() < indent {
		attachFoot(seq, p.takeComments())
	}
	return seq, nil
}

// parseBlockMap parses a block mapping whose keys are at column `indent`.
// firstKey may be a pre-parsed key node (already consumed) or nil.
func (p *yparser) parseBlockMap(indent int, firstKey *Node, head string) (*Node, error) {
	m := emptyMap()
	m.Line, m.Column = p.line, p.col()+1
	if firstKey != nil {
		m.Line, m.Column = firstKey.Line, firstKey.Column
	}
	pendingHead := head
	for {
		var key *Node
		if firstKey != nil {
			key = firstKey
			firstKey = nil
		} else {
			if p.eof() || p.atDocStart() || p.atDocEnd() {
				break
			}
			if p.col() != indent {
				break
			}
			pendingHead = p.takeComments()
			if p.ch() == '?' && (p.at(1) == ' ' || p.at(1) == '\n' || p.pos+1 >= len(p.src)) {
				p.adv()
				p.skipBlanks()
				if p.atLineEnd() {
					if !p.eof() {
						p.skipToNewline()
						p.adv()
					}
					p.skipBlanksAndComments()
					if p.eof() || p.col() <= indent {
						key = nullNode()
					} else {
						k, err := p.parseBlockNodeAtLineStart(p.col())
						if err != nil {
							return nil, err
						}
						key = k
					}
				} else {
					k, err := p.parseBlockNodeAtLineStart(p.col())
					if err != nil {
						return nil, err
					}
					key = k
				}
				p.skipBlanksAndComments()
				if !p.eof() && p.col() == indent && p.ch() == ':' {
					// fallthrough to value parsing below
				} else {
					key.IsMapKey = true
					key.Parent = m
					key.HeadComment = joinComments(pendingHead, key.HeadComment)
					v := nullNode()
					v.Parent = m
					v.Key = key
					m.Content = append(m.Content, key, v)
					continue
				}
			} else {
				k, isKey, err := p.parseNodeOrKey(indent)
				if err != nil {
					return nil, err
				}
				if !isKey {
					return nil, p.errf("yaml: line %d: could not find expected ':'", p.line)
				}
				key = k
			}
		}
		key.IsMapKey = true
		key.Parent = m
		key.HeadComment = joinComments(pendingHead, key.HeadComment)
		pendingHead = ""

		p.skipBlanks()
		if p.ch() != ':' {
			return nil, p.errf("yaml: line %d: could not find expected ':'", p.line)
		}
		p.adv()
		value, err := p.parseAfterIndicator(indent, false)
		if err != nil {
			return nil, err
		}
		value.Parent = m
		value.Key = key
		m.Content = append(m.Content, key, value)

		p.skipBlanksAndComments()
		if p.eof() {
			break
		}
		if p.atDocStart() || p.atDocEnd() {
			break
		}
		if p.col() != indent {
			break
		}
		if p.ch() == '-' && (p.at(1) == ' ' || p.at(1) == '\n') {
			break
		}
	}
	if p.hasPending() {
		if p.eof() || p.col() < indent || p.atDocStart() || p.atDocEnd() {
			if len(m.Content) >= 2 {
				k := m.Content[len(m.Content)-2]
				c := p.takeComments()
				if k.FootComment == "" {
					k.FootComment = c
				} else {
					k.FootComment += "\n" + c
				}
			}
		}
	}
	return m, nil
}

// parseAfterIndicator parses the node following a ':' or '-' indicator.
// parentIndent is the column of the indicator's line content.
func (p *yparser) parseAfterIndicator(parentIndent int, seqEntry bool) (*Node, error) {
	p.skipBlanks()
	if p.atLineEnd() {
		lc := p.takeLineComment()
		if !p.eof() {
			p.adv()
		}
		p.skipBlanksAndComments()
		if p.eof() || p.atDocStart() || p.atDocEnd() {
			n := nullNode()
			n.LineComment = lc
			return n, nil
		}
		c := p.col()
		if c > parentIndent {
			n, err := p.parseBlockNodeAtLineStart(c)
			if err != nil {
				return nil, err
			}
			if lc != "" {
				n.LineComment = lc
			}
			return n, nil
		}
		if !seqEntry && c == parentIndent && p.ch() == '-' && (p.at(1) == ' ' || p.at(1) == '\n' || p.pos+1 >= len(p.src)) {
			n, err := p.parseBlockNodeAtLineStart(c)
			if err != nil {
				return nil, err
			}
			if lc != "" {
				n.LineComment = lc
			}
			return n, nil
		}
		n := nullNode()
		n.LineComment = lc
		return n, nil
	}
	// content on the same line
	col := p.col()
	if seqEntry {
		n, err := p.parseBlockNodeAtLineStart(col)
		if err != nil {
			return nil, err
		}
		return n, nil
	}
	startLine, startCol := p.line, p.col()+1
	anchor, tagText, err := p.parseProps()
	if err != nil {
		return nil, err
	}
	if p.atLineEnd() {
		lc := p.takeLineComment()
		if !p.eof() {
			p.adv()
		}
		p.skipBlanksAndComments()
		if p.eof() || p.col() <= parentIndent || p.atDocStart() || p.atDocEnd() {
			if !p.eof() && p.col() == parentIndent && p.ch() == '-' && (p.at(1) == ' ' || p.at(1) == '\n') {
				n, err := p.parseBlockNodeAtLineStart(p.col())
				if err != nil {
					return nil, err
				}
				if anchor != "" {
					n.Anchor = anchor
				}
				p.applyTag(n, tagText)
				p.registerAnchor(n)
				if lc != "" {
					n.LineComment = lc
				}
				return n, nil
			}
			n := nullNode()
			n.Anchor = anchor
			n.Line, n.Column = startLine, startCol
			p.applyTag(n, tagText)
			n.LineComment = lc
			p.registerAnchor(n)
			return n, nil
		}
		n, err := p.parseBlockNodeAtLineStart(p.col())
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			n.Anchor = anchor
		}
		p.applyTag(n, tagText)
		if lc != "" {
			n.LineComment = lc
		}
		p.registerAnchor(n)
		return n, nil
	}
	var n *Node
	switch p.ch() {
	case '|', '>':
		n, err = p.parseBlockScalar(parentIndent)
		if err != nil {
			return nil, err
		}
	case '[', '{':
		n, err = p.parseFlow()
		if err != nil {
			return nil, err
		}
		n.LineComment = p.takeLineComment()
	case '"':
		s, err := p.scanDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n = scalarNode(tagStr, s)
		n.Style = DoubleQuotedStyle
		n.LineComment = p.takeLineComment()
	case '\'':
		s, err := p.scanSingleQuoted()
		if err != nil {
			return nil, err
		}
		n = scalarNode(tagStr, s)
		n.Style = SingleQuotedStyle
		n.LineComment = p.takeLineComment()
	case '*':
		p.adv()
		st := p.pos
		for !p.eof() && !isBlank(p.ch()) && p.ch() != '\n' && !strings.ContainsRune("[]{},", rune(p.ch())) {
			p.adv()
		}
		n = &Node{Kind: AliasNode, Value: string(p.src[st:p.pos])}
		n.LineComment = p.takeLineComment()
	default:
		s, _, err := p.scanPlain(parentIndent, false)
		if err != nil {
			return nil, err
		}
		n = scalarNode(resolveScalarTag(s), s)
		n.LineComment = p.takeLineComment()
	}
	n.Line, n.Column = startLine, startCol
	if anchor != "" {
		n.Anchor = anchor
	}
	if tagText != "" {
		p.applyTag(n, tagText)
	}
	p.registerAnchor(n)
	return n, nil
}

// ---------------------------------------------------------------------------
// scalars
// ---------------------------------------------------------------------------

func (p *yparser) scanDoubleQuoted() (string, error) {
	p.adv() // opening quote
	var sb strings.Builder
	pendingBreaks := 0
	sawContentOnLine := true
	for {
		if p.eof() {
			return "", p.errf("yaml: found unexpected end of stream")
		}
		c := p.ch()
		if c == '"' {
			p.adv()
			break
		}
		if c == '\n' {
			// line folding
			p.adv()
			nb := 1
			for {
				p.skipBlanks()
				if p.ch() == '\n' {
					nb++
					p.adv()
					continue
				}
				break
			}
			if nb == 1 {
				sb.WriteByte(' ')
			} else {
				sb.WriteString(strings.Repeat("\n", nb-1))
			}
			sawContentOnLine = false
			continue
		}
		_ = pendingBreaks
		_ = sawContentOnLine
		if c == '\\' {
			p.adv()
			e := p.ch()
			if e == '\n' {
				// escaped line break: no folding, strip leading blanks
				p.adv()
				p.skipBlanks()
				continue
			}
			switch e {
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 't', '\t':
				sb.WriteByte('\t')
			case 'n':
				sb.WriteByte('\n')
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'r':
				sb.WriteByte('\r')
			case 'e':
				sb.WriteByte(27)
			case ' ':
				sb.WriteByte(' ')
			case '"':
				sb.WriteByte('"')
			case '/':
				sb.WriteByte('/')
			case '\\':
				sb.WriteByte('\\')
			case 'N':
				sb.WriteString("")
			case '_':
				sb.WriteString(" ")
			case 'L':
				sb.WriteString(" ")
			case 'P':
				sb.WriteString(" ")
			case 'x', 'u', 'U':
				n := 2
				if e == 'u' {
					n = 4
				} else if e == 'U' {
					n = 8
				}
				p.adv()
				v := 0
				for i := 0; i < n; i++ {
					d := hexVal(p.ch())
					if d < 0 {
						return "", p.errf("yaml: found invalid escape sequence")
					}
					v = v*16 + d
					p.adv()
				}
				sb.WriteRune(rune(v))
				continue
			default:
				return "", p.errf("yaml: found unknown escape character %q", string(e))
			}
			p.adv()
			continue
		}
		sb.WriteByte(c)
		p.adv()
	}
	return sb.String(), nil
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

func (p *yparser) scanSingleQuoted() (string, error) {
	p.adv()
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errf("yaml: found unexpected end of stream")
		}
		c := p.ch()
		if c == '\'' {
			if p.at(1) == '\'' {
				sb.WriteByte('\'')
				p.adv()
				p.adv()
				continue
			}
			p.adv()
			break
		}
		if c == '\n' {
			p.adv()
			nb := 1
			for {
				p.skipBlanks()
				if p.ch() == '\n' {
					nb++
					p.adv()
					continue
				}
				break
			}
			if nb == 1 {
				sb.WriteByte(' ')
			} else {
				sb.WriteString(strings.Repeat("\n", nb-1))
			}
			continue
		}
		sb.WriteByte(c)
		p.adv()
	}
	return sb.String(), nil
}

// scanPlain scans a plain scalar starting at the current position.
func (p *yparser) scanPlain(indent int, inFlow bool) (string, bool, error) {
	var lines []string
	var sb strings.Builder
	multiline := false
	for {
		// scan to end of the current line
		for !p.eof() && p.ch() != '\n' {
			c := p.ch()
			if c == '#' && (p.col() == 0 || isBlank(p.at(-1))) {
				break
			}
			if c == ':' {
				nx := p.at(1)
				if nx == ' ' || nx == '\t' || nx == '\n' || p.pos+1 >= len(p.src) {
					break
				}
				if inFlow && (nx == ',' || nx == '}' || nx == ']') {
					break
				}
			}
			if inFlow && strings.ContainsRune(",[]{}", rune(c)) {
				break
			}
			sb.WriteByte(c)
			p.adv()
		}
		lines = append(lines, strings.TrimRight(sb.String(), " \t"))
		sb.Reset()
		// look ahead for a continuation line
		save := p.snapshot()
		if p.eof() || p.ch() != '\n' {
			break
		}
		blanks := 0
		cont := false
		for {
			if p.ch() != '\n' {
				break
			}
			p.adv()
			p.skipBlanks()
			if p.eof() {
				break
			}
			if p.ch() == '\n' {
				blanks++
				continue
			}
			if p.atComment() {
				break
			}
			if p.atDocStart() || p.atDocEnd() {
				break
			}
			if p.col() <= indent {
				break
			}
			if p.ch() == '-' && (p.at(1) == ' ' || p.at(1) == '\n') {
				break
			}
			// check that this line is not a new key
			s2 := p.snapshot()
			isKey := false
			for !p.eof() && p.ch() != '\n' {
				c := p.ch()
				if c == '#' && isBlank(p.at(-1)) {
					break
				}
				if c == ':' {
					nx := p.at(1)
					if nx == ' ' || nx == '\t' || nx == '\n' || p.pos+1 >= len(p.src) {
						isKey = true
					}
					break
				}
				p.adv()
			}
			p.restore(s2)
			if isKey {
				break
			}
			cont = true
			break
		}
		if !cont {
			p.restore(save)
			break
		}
		multiline = true
		if blanks > 0 {
			lines = append(lines, strings.Repeat("\x00", blanks))
		}
	}
	// fold lines
	var out strings.Builder
	for i, l := range lines {
		if i == 0 {
			out.WriteString(l)
			continue
		}
		if strings.HasPrefix(l, "\x00") {
			out.WriteString(strings.Repeat("\n", len(l)))
			continue
		}
		if i > 0 && strings.HasPrefix(lines[i-1], "\x00") {
			out.WriteString(l)
			continue
		}
		out.WriteString(" ")
		out.WriteString(l)
	}
	return out.String(), multiline, nil
}

func (p *yparser) parseBlockScalar(parentIndent int) (*Node, error) {
	style := LiteralStyle
	if p.ch() == '>' {
		style = FoldedStyle
	}
	p.adv()
	chomp := byte(0)
	explicitIndent := 0
	for {
		c := p.ch()
		if c == '-' || c == '+' {
			chomp = c
			p.adv()
			continue
		}
		if c >= '1' && c <= '9' {
			explicitIndent = int(c - '0')
			p.adv()
			continue
		}
		break
	}
	lc := p.takeLineComment()
	if !p.eof() {
		p.adv() // newline
	}
	// determine content indentation
	contentIndent := 0
	if explicitIndent > 0 {
		contentIndent = parentIndent + explicitIndent
	}
	var rawLines []string
	leadingBlanks := 0
	if contentIndent == 0 {
		// find the first non-empty line
		save := p.snapshot()
		for {
			if p.eof() {
				break
			}
			st := p.pos
			for !p.eof() && p.ch() == ' ' {
				p.adv()
			}
			if p.eof() {
				break
			}
			if p.ch() == '\n' {
				if p.pos-st > contentIndent {
					contentIndent = p.pos - st
				}
				leadingBlanks++
				p.adv()
				continue
			}
			ci := p.pos - st
			if ci > contentIndent {
				contentIndent = ci
			}
			break
		}
		p.restore(save)
		if contentIndent <= parentIndent {
			contentIndent = parentIndent + 1
		}
	}
	for {
		if p.eof() {
			break
		}
		// measure indentation
		st := p.pos
		n := 0
		for !p.eof() && p.ch() == ' ' && n < contentIndent {
			p.adv()
			n++
		}
		if p.eof() {
			break
		}
		if p.ch() == '\n' {
			rawLines = append(rawLines, "")
			p.adv()
			continue
		}
		if n < contentIndent {
			p.restore(snap{st, p.line, p.lineStart})
			break
		}
		s := p.pos
		p.skipToNewline()
		rawLines = append(rawLines, string(p.src[s:p.pos]))
		if !p.eof() {
			p.adv()
		}
	}
	value := assembleBlockScalar(rawLines, style, chomp)
	n := scalarNode(tagStr, value)
	n.Style = style
	n.LineComment = lc
	return n, nil
}

func assembleBlockScalar(lines []string, style Style, chomp byte) string {
	// strip trailing empty lines, remembering how many there were
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	var sb strings.Builder
	if style == LiteralStyle {
		for _, l := range lines {
			sb.WriteString(l)
			sb.WriteByte('\n')
		}
	} else {
		for i, l := range lines {
			if i == 0 {
				sb.WriteString(l)
				continue
			}
			prev := lines[i-1]
			if l == "" {
				sb.WriteByte('\n')
				continue
			}
			if prev == "" {
				sb.WriteString(l)
				continue
			}
			if strings.HasPrefix(l, " ") || strings.HasPrefix(l, "\t") || strings.HasPrefix(prev, " ") || strings.HasPrefix(prev, "\t") {
				sb.WriteByte('\n')
			} else {
				sb.WriteByte(' ')
			}
			sb.WriteString(l)
		}
		if len(lines) > 0 {
			sb.WriteByte('\n')
		}
	}
	s := sb.String()
	switch chomp {
	case '-':
		s = strings.TrimRight(s, "\n")
	case '+':
		s += strings.Repeat("\n", trailing)
	default:
		// clip: single trailing newline (already present if there was content)
		if len(lines) == 0 {
			s = ""
		}
	}
	return s
}

// ---------------------------------------------------------------------------
// flow collections
// ---------------------------------------------------------------------------

func (p *yparser) skipFlowSpace() {
	for {
		p.skipBlanks()
		if p.atComment() {
			cs := p.pos
			p.skipToNewline()
			p.pending = append(p.pending, strings.TrimRight(string(p.src[cs:p.pos]), " \t"))
			p.seenComment = true
			continue
		}
		if p.ch() == '\n' {
			p.adv()
			continue
		}
		return
	}
}

func (p *yparser) parseFlow() (*Node, error) {
	open := p.ch()
	startLine, startCol := p.line, p.col()+1
	p.adv()
	var n *Node
	if open == '[' {
		n = emptySeq()
	} else {
		n = emptyMap()
	}
	n.Style = FlowStyle
	n.Line, n.Column = startLine, startCol
	closer := byte(']')
	if open == '{' {
		closer = '}'
	}
	for {
		p.skipFlowSpace()
		if p.eof() {
			return nil, p.errf("yaml: line %d: did not find expected ',' or '%c'", p.line, closer)
		}
		if p.ch() == closer {
			p.adv()
			break
		}
		if p.ch() == ',' {
			p.adv()
			continue
		}
		item, err := p.parseFlowNode()
		if err != nil {
			return nil, err
		}
		p.skipFlowSpace()
		if p.ch() == ':' {
			nx := p.at(1)
			if open == '{' || nx == ' ' || nx == '\t' || nx == '\n' {
				p.adv()
				p.skipFlowSpace()
				var v *Node
				if p.ch() == ',' || p.ch() == closer {
					v = nullNode()
				} else {
					v, err = p.parseFlowNode()
					if err != nil {
						return nil, err
					}
				}
				if open == '[' {
					// single pair mapping inside a sequence
					m := emptyMap()
					m.Style = FlowStyle
					item.IsMapKey = true
					item.Parent = m
					v.Parent = m
					v.Key = item
					m.Content = append(m.Content, item, v)
					m.Parent = n
					n.Content = append(n.Content, m)
					continue
				}
				item.IsMapKey = true
				item.Parent = n
				v.Parent = n
				v.Key = item
				n.Content = append(n.Content, item, v)
				continue
			}
		}
		if open == '{' {
			item.IsMapKey = true
			item.Parent = n
			v := nullNode()
			v.Parent = n
			v.Key = item
			n.Content = append(n.Content, item, v)
			continue
		}
		item.Parent = n
		n.Content = append(n.Content, item)
	}
	return n, nil
}

func (p *yparser) parseFlowNode() (*Node, error) {
	startLine, startCol := p.line, p.col()+1
	anchor, tagText, err := p.parseProps()
	if err != nil {
		return nil, err
	}
	p.skipFlowSpace()
	var n *Node
	switch p.ch() {
	case '[', '{':
		n, err = p.parseFlow()
		if err != nil {
			return nil, err
		}
	case '"':
		s, err := p.scanDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n = scalarNode(tagStr, s)
		n.Style = DoubleQuotedStyle
	case '\'':
		s, err := p.scanSingleQuoted()
		if err != nil {
			return nil, err
		}
		n = scalarNode(tagStr, s)
		n.Style = SingleQuotedStyle
	case '*':
		p.adv()
		st := p.pos
		for !p.eof() && !isBlank(p.ch()) && p.ch() != '\n' && !strings.ContainsRune("[]{},", rune(p.ch())) {
			p.adv()
		}
		n = &Node{Kind: AliasNode, Value: string(p.src[st:p.pos])}
	default:
		s, _, err := p.scanPlain(0, true)
		if err != nil {
			return nil, err
		}
		n = scalarNode(resolveScalarTag(s), s)
	}
	n.Line, n.Column = startLine, startCol
	if anchor != "" {
		n.Anchor = anchor
	}
	if tagText != "" {
		p.applyTag(n, tagText)
	}
	p.registerAnchor(n)
	return n, nil
}

