func parseTimestampValue(s string) (time.Time, bool) {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	if i != 4 || i == len(s) || s[i] != '-' {
		return time.Time{}, false
	}
	for _, f := range timestampFormats {
		if t, err := time.Parse(f, s); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

// yamlStyleFloat matches the YAML core-schema float production.
func isYAMLStyleFloat(s string) bool {
	i := 0
	if i < len(s) && (s[i] == '+' || s[i] == '-') {
		i++
	}
	digits := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
		digits++
	}
	frac := 0
	if i < len(s) && s[i] == '.' {
		i++
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
			frac++
		}
		if digits == 0 && frac == 0 {
			return false
		}
	} else if digits == 0 {
		return false
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i < len(s) && (s[i] == '+' || s[i] == '-') {
			i++
		}
		ed := 0
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
			ed++
		}
		if ed == 0 {
			return false
		}
	}
	return i == len(s)
}

// resolveScalarTag determines the implicit tag of a plain scalar.
func resolveScalarTag(in string) string {
	if t, ok := resolveMap[in]; ok {
		return t
	}
	if in == "" {
		return tagNull
	}
	c := in[0]
	hint := byte(0)
	switch {
	case c == '+' || c == '-':
		hint = 'S'
	case c >= '0' && c <= '9':
		hint = 'D'
	case c == '.':
		hint = '.'
	}
	switch hint {
	case '.':
		if _, err := strconv.ParseFloat(in, 64); err == nil {
			return tagFloat
		}
	case 'D', 'S':
		if _, ok := parseTimestampValue(in); ok {
			return tagTimestamp
		}
		plain := strings.ReplaceAll(in, "_", "")
		// Negative zero is emitted as a float by the reference implementation.
		if plain == "-0" {
			return tagFloat
		}
		if _, err := strconv.ParseInt(plain, 0, 64); err == nil {
			return tagInt
		}
		if _, err := strconv.ParseUint(plain, 10, 64); err == nil {
			return tagInt
		}
		if isYAMLStyleFloat(plain) {
			if _, err := strconv.ParseFloat(plain, 64); err == nil {
				return tagFloat
			}
		}
		if strings.HasPrefix(plain, "0b") {
			if _, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
				return tagInt
			}
		} else if strings.HasPrefix(plain, "-0b") {
			if _, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
				return tagInt
			}
		}
	}
	return tagStr
}

// ---------------------------------------------------------------------------
// numeric conversion helpers (used by arithmetic and JSON output)
// ---------------------------------------------------------------------------

// parseIntValue mirrors the reference implementation's !!int conversion.
func parseIntValue(s string) (int64, error) {
	clean := strings.ReplaceAll(s, "_", "")
	if strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0X") {
		return strconv.ParseInt(clean[2:], 16, 64)
	}
	if strings.HasPrefix(clean, "0o") {
		return strconv.ParseInt(clean[2:], 8, 64)
	}
	v, err := strconv.ParseInt(clean, 10, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok {
			ne.Num = s
		}
	}
	return v, err
}

func parseFloatValue(s string) (float64, error) {
	clean := strings.ReplaceAll(s, "_", "")
	switch strings.ToLower(clean) {
	case ".inf", "+.inf":
		return math.Inf(1), nil
	case "-.inf":
		return math.Inf(-1), nil
	case ".nan":
		return math.NaN(), nil
	}
	v, err := strconv.ParseFloat(clean, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok {
			ne.Num = s
		}
	}
	return v, err
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return "+Inf"
	}
	if math.IsInf(f, -1) {
		return "-Inf"
	}
	if math.IsNaN(f) {
		return "NaN"
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func validUTF8(s string) bool { return utf8.ValidString(s) }
